-- Generated by `umd-events snowflake-sql`. Run after snowflake_schema.sql.
-- 1. Create the stage, then upload every data/exports/<TABLE>.jsonl into a folder named after its table:
--    @UMD_EVENTS_STAGE/EVENTS/EVENTS.jsonl, @UMD_EVENTS_STAGE/VENUES/VENUES.jsonl, ...
CREATE STAGE IF NOT EXISTS UMD_EVENTS_STAGE FILE_FORMAT = (TYPE = JSON);

-- 2. Load each table (COPY into a temp table, then MERGE on the key).

-- RAW_EVENTS
CREATE OR REPLACE TEMPORARY TABLE RAW_EVENTS_STAGING LIKE RAW_EVENTS;
COPY INTO RAW_EVENTS_STAGING
FROM (
    SELECT
        $1:ingestion_id::STRING AS INGESTION_ID,
        $1:source::STRING AS SOURCE,
        $1:source_event_id::STRING AS SOURCE_EVENT_ID,
        $1:source_url::STRING AS SOURCE_URL,
        $1:raw_data AS RAW_DATA,
        $1:scraped_at::TIMESTAMP_TZ AS SCRAPED_AT,
        $1:scraper_version::STRING AS SCRAPER_VERSION,
        $1:content_hash::STRING AS CONTENT_HASH
    FROM @UMD_EVENTS_STAGE/RAW_EVENTS/
)
FILE_FORMAT = (TYPE = JSON) ON_ERROR = ABORT_STATEMENT;
MERGE INTO RAW_EVENTS t
USING (SELECT * FROM RAW_EVENTS_STAGING QUALIFY ROW_NUMBER() OVER (PARTITION BY INGESTION_ID ORDER BY INGESTION_ID) = 1) s
ON t.INGESTION_ID = s.INGESTION_ID
WHEN MATCHED THEN UPDATE SET SOURCE = s.SOURCE, SOURCE_EVENT_ID = s.SOURCE_EVENT_ID, SOURCE_URL = s.SOURCE_URL, RAW_DATA = s.RAW_DATA, SCRAPED_AT = s.SCRAPED_AT, SCRAPER_VERSION = s.SCRAPER_VERSION, CONTENT_HASH = s.CONTENT_HASH
WHEN NOT MATCHED THEN INSERT (INGESTION_ID, SOURCE, SOURCE_EVENT_ID, SOURCE_URL, RAW_DATA, SCRAPED_AT, SCRAPER_VERSION, CONTENT_HASH) VALUES (s.INGESTION_ID, s.SOURCE, s.SOURCE_EVENT_ID, s.SOURCE_URL, s.RAW_DATA, s.SCRAPED_AT, s.SCRAPER_VERSION, s.CONTENT_HASH);

-- EVENTS
CREATE OR REPLACE TEMPORARY TABLE EVENTS_STAGING LIKE EVENTS;
COPY INTO EVENTS_STAGING
FROM (
    SELECT
        $1:event_id::STRING AS EVENT_ID,
        $1:title::STRING AS TITLE,
        $1:short_description::STRING AS SHORT_DESCRIPTION,
        $1:description::STRING AS DESCRIPTION,
        $1:start_time::TIMESTAMP_TZ AS START_TIME,
        $1:end_time::TIMESTAMP_TZ AS END_TIME,
        $1:all_day::BOOLEAN AS ALL_DAY,
        $1:venue_id::STRING AS VENUE_ID,
        $1:venue_name::STRING AS VENUE_NAME,
        $1:address::STRING AS ADDRESS,
        $1:latitude::FLOAT AS LATITUDE,
        $1:longitude::FLOAT AS LONGITUDE,
        $1:distance_miles::FLOAT AS DISTANCE_MILES,
        $1:organizer_name::STRING AS ORGANIZER_NAME,
        $1:source::STRING AS SOURCE,
        $1:source_event_id::STRING AS SOURCE_EVENT_ID,
        $1:source_url::STRING AS SOURCE_URL,
        $1:sources::ARRAY AS SOURCES,
        $1:image_url::STRING AS IMAGE_URL,
        $1:registration_url::STRING AS REGISTRATION_URL,
        $1:price_min::FLOAT AS PRICE_MIN,
        $1:price_max::FLOAT AS PRICE_MAX,
        $1:is_free::BOOLEAN AS IS_FREE,
        $1:price_display::STRING AS PRICE_DISPLAY,
        $1:is_umd::BOOLEAN AS IS_UMD,
        $1:is_online::BOOLEAN AS IS_ONLINE,
        $1:event_type::STRING AS EVENT_TYPE,
        $1:tags::ARRAY AS TAGS,
        $1:extra AS EXTRA,
        $1:content_hash::STRING AS CONTENT_HASH,
        $1:created_at::TIMESTAMP_TZ AS CREATED_AT,
        $1:updated_at::TIMESTAMP_TZ AS UPDATED_AT,
        $1:last_seen_at::TIMESTAMP_TZ AS LAST_SEEN_AT
    FROM @UMD_EVENTS_STAGE/EVENTS/
)
FILE_FORMAT = (TYPE = JSON) ON_ERROR = ABORT_STATEMENT;
MERGE INTO EVENTS t
USING (SELECT * FROM EVENTS_STAGING QUALIFY ROW_NUMBER() OVER (PARTITION BY EVENT_ID ORDER BY EVENT_ID) = 1) s
ON t.EVENT_ID = s.EVENT_ID
WHEN MATCHED THEN UPDATE SET TITLE = s.TITLE, SHORT_DESCRIPTION = s.SHORT_DESCRIPTION, DESCRIPTION = s.DESCRIPTION, START_TIME = s.START_TIME, END_TIME = s.END_TIME, ALL_DAY = s.ALL_DAY, VENUE_ID = s.VENUE_ID, VENUE_NAME = s.VENUE_NAME, ADDRESS = s.ADDRESS, LATITUDE = s.LATITUDE, LONGITUDE = s.LONGITUDE, DISTANCE_MILES = s.DISTANCE_MILES, ORGANIZER_NAME = s.ORGANIZER_NAME, SOURCE = s.SOURCE, SOURCE_EVENT_ID = s.SOURCE_EVENT_ID, SOURCE_URL = s.SOURCE_URL, SOURCES = s.SOURCES, IMAGE_URL = s.IMAGE_URL, REGISTRATION_URL = s.REGISTRATION_URL, PRICE_MIN = s.PRICE_MIN, PRICE_MAX = s.PRICE_MAX, IS_FREE = s.IS_FREE, PRICE_DISPLAY = s.PRICE_DISPLAY, IS_UMD = s.IS_UMD, IS_ONLINE = s.IS_ONLINE, EVENT_TYPE = s.EVENT_TYPE, TAGS = s.TAGS, EXTRA = s.EXTRA, CONTENT_HASH = s.CONTENT_HASH, CREATED_AT = s.CREATED_AT, UPDATED_AT = s.UPDATED_AT, LAST_SEEN_AT = s.LAST_SEEN_AT
WHEN NOT MATCHED THEN INSERT (EVENT_ID, TITLE, SHORT_DESCRIPTION, DESCRIPTION, START_TIME, END_TIME, ALL_DAY, VENUE_ID, VENUE_NAME, ADDRESS, LATITUDE, LONGITUDE, DISTANCE_MILES, ORGANIZER_NAME, SOURCE, SOURCE_EVENT_ID, SOURCE_URL, SOURCES, IMAGE_URL, REGISTRATION_URL, PRICE_MIN, PRICE_MAX, IS_FREE, PRICE_DISPLAY, IS_UMD, IS_ONLINE, EVENT_TYPE, TAGS, EXTRA, CONTENT_HASH, CREATED_AT, UPDATED_AT, LAST_SEEN_AT) VALUES (s.EVENT_ID, s.TITLE, s.SHORT_DESCRIPTION, s.DESCRIPTION, s.START_TIME, s.END_TIME, s.ALL_DAY, s.VENUE_ID, s.VENUE_NAME, s.ADDRESS, s.LATITUDE, s.LONGITUDE, s.DISTANCE_MILES, s.ORGANIZER_NAME, s.SOURCE, s.SOURCE_EVENT_ID, s.SOURCE_URL, s.SOURCES, s.IMAGE_URL, s.REGISTRATION_URL, s.PRICE_MIN, s.PRICE_MAX, s.IS_FREE, s.PRICE_DISPLAY, s.IS_UMD, s.IS_ONLINE, s.EVENT_TYPE, s.TAGS, s.EXTRA, s.CONTENT_HASH, s.CREATED_AT, s.UPDATED_AT, s.LAST_SEEN_AT);

-- EVENT_SOURCES
CREATE OR REPLACE TEMPORARY TABLE EVENT_SOURCES_STAGING LIKE EVENT_SOURCES;
COPY INTO EVENT_SOURCES_STAGING
FROM (
    SELECT
        $1:canonical_event_id::STRING AS CANONICAL_EVENT_ID,
        $1:source::STRING AS SOURCE,
        $1:source_event_id::STRING AS SOURCE_EVENT_ID,
        $1:source_url::STRING AS SOURCE_URL,
        $1:source_record_id::STRING AS SOURCE_RECORD_ID,
        $1:discovered_at::TIMESTAMP_TZ AS DISCOVERED_AT,
        $1:last_seen_at::TIMESTAMP_TZ AS LAST_SEEN_AT
    FROM @UMD_EVENTS_STAGE/EVENT_SOURCES/
)
FILE_FORMAT = (TYPE = JSON) ON_ERROR = ABORT_STATEMENT;
MERGE INTO EVENT_SOURCES t
USING (SELECT * FROM EVENT_SOURCES_STAGING QUALIFY ROW_NUMBER() OVER (PARTITION BY SOURCE, SOURCE_EVENT_ID ORDER BY SOURCE, SOURCE_EVENT_ID) = 1) s
ON t.SOURCE = s.SOURCE AND t.SOURCE_EVENT_ID = s.SOURCE_EVENT_ID
WHEN MATCHED THEN UPDATE SET CANONICAL_EVENT_ID = s.CANONICAL_EVENT_ID, SOURCE_URL = s.SOURCE_URL, SOURCE_RECORD_ID = s.SOURCE_RECORD_ID, DISCOVERED_AT = s.DISCOVERED_AT, LAST_SEEN_AT = s.LAST_SEEN_AT
WHEN NOT MATCHED THEN INSERT (CANONICAL_EVENT_ID, SOURCE, SOURCE_EVENT_ID, SOURCE_URL, SOURCE_RECORD_ID, DISCOVERED_AT, LAST_SEEN_AT) VALUES (s.CANONICAL_EVENT_ID, s.SOURCE, s.SOURCE_EVENT_ID, s.SOURCE_URL, s.SOURCE_RECORD_ID, s.DISCOVERED_AT, s.LAST_SEEN_AT);

-- VENUES
CREATE OR REPLACE TEMPORARY TABLE VENUES_STAGING LIKE VENUES;
COPY INTO VENUES_STAGING
FROM (
    SELECT
        $1:venue_id::STRING AS VENUE_ID,
        $1:canonical_name::STRING AS CANONICAL_NAME,
        $1:address::STRING AS ADDRESS,
        $1:latitude::FLOAT AS LATITUDE,
        $1:longitude::FLOAT AS LONGITUDE,
        $1:aliases::ARRAY AS ALIASES,
        $1:is_umd::BOOLEAN AS IS_UMD
    FROM @UMD_EVENTS_STAGE/VENUES/
)
FILE_FORMAT = (TYPE = JSON) ON_ERROR = ABORT_STATEMENT;
MERGE INTO VENUES t
USING (SELECT * FROM VENUES_STAGING QUALIFY ROW_NUMBER() OVER (PARTITION BY VENUE_ID ORDER BY VENUE_ID) = 1) s
ON t.VENUE_ID = s.VENUE_ID
WHEN MATCHED THEN UPDATE SET CANONICAL_NAME = s.CANONICAL_NAME, ADDRESS = s.ADDRESS, LATITUDE = s.LATITUDE, LONGITUDE = s.LONGITUDE, ALIASES = s.ALIASES, IS_UMD = s.IS_UMD
WHEN NOT MATCHED THEN INSERT (VENUE_ID, CANONICAL_NAME, ADDRESS, LATITUDE, LONGITUDE, ALIASES, IS_UMD) VALUES (s.VENUE_ID, s.CANONICAL_NAME, s.ADDRESS, s.LATITUDE, s.LONGITUDE, s.ALIASES, s.IS_UMD);

-- INGESTION_RUNS
CREATE OR REPLACE TEMPORARY TABLE INGESTION_RUNS_STAGING LIKE INGESTION_RUNS;
COPY INTO INGESTION_RUNS_STAGING
FROM (
    SELECT
        $1:run_id::STRING AS RUN_ID,
        $1:source::STRING AS SOURCE,
        $1:started_at::TIMESTAMP_TZ AS STARTED_AT,
        $1:completed_at::TIMESTAMP_TZ AS COMPLETED_AT,
        $1:status::STRING AS STATUS,
        $1:events_found::INTEGER AS EVENTS_FOUND,
        $1:events_inserted::INTEGER AS EVENTS_INSERTED,
        $1:events_updated::INTEGER AS EVENTS_UPDATED,
        $1:events_rejected::INTEGER AS EVENTS_REJECTED,
        $1:error_message::STRING AS ERROR_MESSAGE
    FROM @UMD_EVENTS_STAGE/INGESTION_RUNS/
)
FILE_FORMAT = (TYPE = JSON) ON_ERROR = ABORT_STATEMENT;
MERGE INTO INGESTION_RUNS t
USING (SELECT * FROM INGESTION_RUNS_STAGING QUALIFY ROW_NUMBER() OVER (PARTITION BY RUN_ID, SOURCE ORDER BY RUN_ID, SOURCE) = 1) s
ON t.RUN_ID = s.RUN_ID AND t.SOURCE = s.SOURCE
WHEN MATCHED THEN UPDATE SET STARTED_AT = s.STARTED_AT, COMPLETED_AT = s.COMPLETED_AT, STATUS = s.STATUS, EVENTS_FOUND = s.EVENTS_FOUND, EVENTS_INSERTED = s.EVENTS_INSERTED, EVENTS_UPDATED = s.EVENTS_UPDATED, EVENTS_REJECTED = s.EVENTS_REJECTED, ERROR_MESSAGE = s.ERROR_MESSAGE
WHEN NOT MATCHED THEN INSERT (RUN_ID, SOURCE, STARTED_AT, COMPLETED_AT, STATUS, EVENTS_FOUND, EVENTS_INSERTED, EVENTS_UPDATED, EVENTS_REJECTED, ERROR_MESSAGE) VALUES (s.RUN_ID, s.SOURCE, s.STARTED_AT, s.COMPLETED_AT, s.STATUS, s.EVENTS_FOUND, s.EVENTS_INSERTED, s.EVENTS_UPDATED, s.EVENTS_REJECTED, s.ERROR_MESSAGE);

-- EVENT_EMBEDDINGS
CREATE OR REPLACE TEMPORARY TABLE EVENT_EMBEDDINGS_STAGING LIKE EVENT_EMBEDDINGS;
COPY INTO EVENT_EMBEDDINGS_STAGING
FROM (
    SELECT
        $1:event_id::STRING AS EVENT_ID,
        $1:model::STRING AS MODEL,
        $1:embedding::ARRAY::VECTOR(FLOAT, 384) AS EMBEDDING,
        $1:content_hash::STRING AS CONTENT_HASH,
        $1:created_at::TIMESTAMP_TZ AS CREATED_AT
    FROM @UMD_EVENTS_STAGE/EVENT_EMBEDDINGS/
)
FILE_FORMAT = (TYPE = JSON) ON_ERROR = ABORT_STATEMENT;
MERGE INTO EVENT_EMBEDDINGS t
USING (SELECT * FROM EVENT_EMBEDDINGS_STAGING QUALIFY ROW_NUMBER() OVER (PARTITION BY EVENT_ID ORDER BY EVENT_ID) = 1) s
ON t.EVENT_ID = s.EVENT_ID
WHEN MATCHED THEN UPDATE SET MODEL = s.MODEL, EMBEDDING = s.EMBEDDING, CONTENT_HASH = s.CONTENT_HASH, CREATED_AT = s.CREATED_AT
WHEN NOT MATCHED THEN INSERT (EVENT_ID, MODEL, EMBEDDING, CONTENT_HASH, CREATED_AT) VALUES (s.EVENT_ID, s.MODEL, s.EMBEDDING, s.CONTENT_HASH, s.CREATED_AT);

-- 3. Remove future events that are no longer listed.
DELETE FROM EVENTS WHERE start_time >= CURRENT_TIMESTAMP() AND event_id NOT IN (SELECT event_id FROM EVENTS_STAGING) AND EXISTS (SELECT 1 FROM EVENTS_STAGING);
DELETE FROM EVENT_SOURCES WHERE canonical_event_id NOT IN (SELECT event_id FROM EVENTS) AND EXISTS (SELECT 1 FROM EVENTS_STAGING);
